    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited or grid[r][c] == 0:
                continue
            color = grid[r][c]
            comp = []
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                comp.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, cc) not in visited:
                        stack.append((nr, nc))
            comp.sort()
            components.append((color, frozenset(comp), len(comp)))
    return components

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    components = get_components(grid)
    by_size = {}
    for color, comp, size in components:
        if size not in by_size:
            by_size[size] = []
        by_size[size].append((color, comp))
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for size, comps in by_size.items():
        colors = sorted(set(c for c, _ in comps))

        if size >= 5:
            max_color = max(colors)
            for color, comp in comps:
                for r, cc in comp:
                    output[r][cc] = max_color

        elif size == 3:
            def get_dist(comp, rows, cols):
                centroid = [sum(r for r, cc in comp) / len(comp), sum(cc for r, cc in comp) / len(comp)]
                return abs(centroid[0] - rows/2) + abs(centroid[1] - cols/2)

            sorted_comps = sorted(comps, key=lambda x: get_dist(x[1], rows, cols))
            non_one_colors = sorted(set(c for c, _ in comps if c != 1))

            print(f"Size-3 components ({len(sorted_comps)}):")
            for idx, (c, comp) in enumerate(sorted_comps):
                dist = get_dist(comp, rows, cols)
                output_line = []
                for r, cc in comp:
                    if c != 1:
                        output_line.append(f"keep {c}")
                    else:
                        new_val = non_one_colors[-1] if idx == 0 else non_one_colors[0]
                        output_line.append(f"1->{new_val} (i={idx}, dist={dist:.2f})")
                print(f"  [{idx}] dist={dist:.2f} color={c}, output: {output_line}")

            for i, (c, comp) in enumerate(sorted_comps):
                for r, cc in comp:
                    if c != 1:
                        pass
                    else:
                        if i == 0:
                            output[r][cc] = non_one_colors[-1]
                        else:
                            output[r][cc] = non_one_colors[0]

    return output

